/* =========================================================
   HOOK: revelar elementos al hacer scroll (IntersectionObserver)
   ========================================================= */
function useInView(threshold = 0.15) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setInView(true);
            obs.disconnect();
          }
        });
      },
      { threshold }
    );
    obs.observe(node);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, inView];
}

function Reveal({ tag = "div", className = "", style, children, delay = 0, threshold }) {
  const [ref, inView] = useInView(threshold);
  const Tag = tag;
  return (
    <Tag
      ref={ref}
      className={`${className} ${inView ? "visible" : ""}`}
      style={{ ...style, transitionDelay: delay ? `${delay}s` : undefined }}
    >
      {children}
    </Tag>
  );
}

function Counter({ target, prefix = "", suffix = "", trigger }) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!trigger) return;
    const duration = 1500;
    const start = Date.now();
    let raf;
    const tick = () => {
      const progress = Math.min((Date.now() - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setVal(Math.floor(eased * target));
      if (progress < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [trigger, target]);
  return (
    <span className="stat-num">
      {prefix}
      {val.toLocaleString()}
      {suffix}
    </span>
  );
}

