/* =========================================================
   APP PRINCIPAL
   ========================================================= */
export default function BitTrackRoverApp() {
  const [page, setPage] = useState("landing"); // landing | register | home | datos | mirover
  const [theme, setTheme] = useState("light"); // toggle unico para toda la app
  const [usuario, setUsuario] = useState(null);

  const [hospitales] = useState(HOSPITALES_INICIALES);
  const [robots, setRobots] = useState(ROBOTS_INICIALES);
  const [usuarios, setUsuarios] = useState(USUARIOS_INICIALES);

  const [loginError, setLoginError] = useState("");
  const [regError, setRegError] = useState("");
  const [regSuccess, setRegSuccess] = useState("");

  const toggleTheme = () => setTheme((t) => (t === "light" ? "dark" : "light"));

  const goTo = (p) => {
    setPage(p);
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
  };

  const handleLogin = (email, password) => {
    setLoginError("");
    if (!email || !password) {
      setLoginError("Completá email y contraseña.");
      return;
    }
    const found = usuarios.find((u) => u.email === email.trim() && u.password === password);
    if (!found) {
      setLoginError("Email o contraseña incorrectos.");
      return;
    }
    const hospital = hospitales.find((h) => h.id_hospital === found.fk_hospital);
    const robot = robots.find((r) => r.id_robot === found.fk_robot);
    setUsuario({
      id_usuario: found.id_usuario,
      nombre: found.nombre,
      email: found.email,
      hospital: hospital ? hospital.nombre : "—",
      ciudad: hospital ? hospital.ciudad : "—",
      robot_codigo: robot ? robot.codigo : null,
      robot_modelo: robot ? robot.modelo : null,
    });
    goTo("home");
  };

  const handleRegister = ({ nombre, email, password, hospitalId }) => {
    setRegError("");
    setRegSuccess("");
    if (!nombre || !email || !password || !hospitalId) {
      setRegError("Por favor completá todos los campos.");
      return;
    }
    if (usuarios.some((u) => u.email === email.trim())) {
      setRegError("Ya existe una cuenta con ese email.");
      return;
    }
    const robotDisponible = robots.find((r) => r.disponible);
    if (!robotDisponible) {
      setRegError("No hay rovers disponibles en este momento.");
      return;
    }
    const newId = usuarios.length ? Math.max(...usuarios.map((u) => u.id_usuario)) + 1 : 1;
    const nuevoUsuario = {
      id_usuario: newId,
      nombre: nombre.trim(),
      email: email.trim(),
      password,
      fk_hospital: Number(hospitalId),
      fk_robot: robotDisponible.id_robot,
    };
    setUsuarios((prev) => [...prev, nuevoUsuario]);
    setRobots((prev) =>
      prev.map((r) => (r.id_robot === robotDisponible.id_robot ? { ...r, disponible: false } : r))
    );
    setRegSuccess(`¡Cuenta creada! Tu rover asignado es: ${robotDisponible.codigo}. Ahora iniciá sesión.`);
  };

  const handleLogout = () => {
    setUsuario(null);
    goTo("landing");
  };

  return (
    <div className={`bt-root theme-${theme}`}>
      <style>{CSS}</style>
      {page === "landing" && (
        <LandingPage
          theme={theme}
          toggleTheme={toggleTheme}
          onLogin={handleLogin}
          loginError={loginError}
          goTo={goTo}
        />
      )}
      {page === "register" && (
        <RegisterPage
          hospitales={hospitales}
          onRegister={handleRegister}
          error={regError}
          success={regSuccess}
          goTo={goTo}
        />
      )}
      {page === "home" && usuario && (
        <HomePage usuario={usuario} theme={theme} toggleTheme={toggleTheme} onLogout={handleLogout} goTo={goTo} />
      )}
      {page === "datos" && usuario && (
        <DatosPage usuario={usuario} theme={theme} toggleTheme={toggleTheme} goTo={goTo} />
      )}
      {page === "mirover" && usuario && (
        <RoverPage usuario={usuario} onLogout={handleLogout} goTo={goTo} />
      )}
      {(page === "home" || page === "datos" || page === "mirover") && !usuario && (
        <div className="bt-guard">
          <p>Necesitás iniciar sesión para ver esta página.</p>
          <button className="btn" onClick={() => goTo("landing")}>
            Ir al inicio
          </button>
        </div>
      )}
    </div>
  );
}

